import os
import sys
import shutil
import random
import string
import time
from datetime import datetime, timedelta

TARGET_DIR = './target'
ENCRYPTION_KEYS_FILE = 'encryption_keys.txt'
RESTORE_INSTRUCTIONS_FILE = 'RESTORE_INSTRUCTIONS.txt'
MAX_FILE_AGE_DAYS = 30  # Files older than this will be cleaned up
PERIODIC_TASK_ITERATIONS = 3
SELF_CHECK_TASK = True  # Enable startup integrity check


def generate_encryption_key():
    """Generate a random encryption key."""
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))


def encrypt_file(filepath, key):
    """Encrypt file contents (basic obfuscation for demonstration)."""
    try:
        with open(filepath, 'rb') as f:
            data = f.read()
        encrypted_data = bytes((byte + ord(key[i % len(key)])) % 256 for i, byte in enumerate(data))
        with open(filepath, 'wb') as f:
            f.write(encrypted_data)
    except Exception as e:
        print(f"Error encrypting {filepath}: {e}", file=sys.stderr)


def decrypt_file(filepath, key):
    """Decrypt file contents (basic de-obfuscation)."""
    try:
        with open(filepath, 'rb') as f:
            data = f.read()
        decrypted_data = bytes((byte - ord(key[i % len(key)])) % 256 for i, byte in enumerate(data))
        with open(filepath, 'wb') as f:
            f.write(decrypted_data)
    except Exception as e:
        print(f"Error decrypting {filepath}: {e}", file=sys.stderr)


def create_restore_instructions():
    """Create the restore instructions file."""
    instructions = (
        "RESTORE INSTRUCTIONS:\n"
        "1. Locate the encryption_keys.txt file in the target directory.\n"
        "2. Use the keys listed in the file to decrypt each encrypted file.\n"
        "3. Use the provided Python program or any compatible tool to decrypt files.\n"
        "4. To optimize storage, periodically clean old files.\n"
        "5. Ensure the integrity of the files by performing a self-check after restoration.\n"
    )
    try:
        with open(os.path.join(TARGET_DIR, RESTORE_INSTRUCTIONS_FILE), 'w') as f:
            f.write(instructions)
    except Exception as e:
        print(f"Error creating restore instructions: {e}", file=sys.stderr)


def clean_old_files():
    """Delete files older than MAX_FILE_AGE_DAYS."""
    try:
        cutoff_date = datetime.now() - timedelta(days=MAX_FILE_AGE_DAYS)
        for filename in os.listdir(TARGET_DIR):
            filepath = os.path.join(TARGET_DIR, filename)
            if os.path.isfile(filepath):
                file_mtime = datetime.fromtimestamp(os.path.getmtime(filepath))
                if file_mtime < cutoff_date:
                    os.remove(filepath)
                    print(f"Deleted old file: {filename}")
    except Exception as e:
        print(f"Error cleaning old files: {e}", file=sys.stderr)


def register_startup_self_check():
    """Simulate registration of a startup self-check task."""
    print("Startup self-check task registered (simulated).")


def perform_periodic_tasks():
    """Perform periodic maintenance tasks."""
    for _ in range(PERIODIC_TASK_ITERATIONS):
        clean_old_files()
        time.sleep(1)  # Simulate periodic task delay


def check_directory_integrity():
    """Perform a self-check to ensure all expected files are present."""
    try:
        missing_files = []
        required_files = {ENCRYPTION_KEYS_FILE, RESTORE_INSTRUCTIONS_FILE}
        for required_file in required_files:
            if not os.path.exists(os.path.join(TARGET_DIR, required_file)):
                missing_files.append(required_file)
        if missing_files:
            print(f"Integrity check failed. Missing files: {', '.join(missing_files)}", file=sys.stderr)
        else:
            print("Integrity check passed.")
    except Exception as e:
        print(f"Error during integrity check: {e}", file=sys.stderr)


def main():
    # Ensure target directory exists
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
    except Exception as e:
        print(f"Error creating target directory: {e}", file=sys.stderr)
        return

    # Generate encryption keys and encrypt files
    keys = {}
    try:
        for filename in os.listdir(TARGET_DIR):
            filepath = os.path.join(TARGET_DIR, filename)
            if os.path.isfile(filepath) and filename not in {ENCRYPTION_KEYS_FILE, RESTORE_INSTRUCTIONS_FILE}:
                key = generate_encryption_key()
                keys[filename] = key
                encrypt_file(filepath, key)
    except Exception as e:
        print(f"Error processing files in target directory: {e}", file=sys.stderr)

    # Save encryption keys to file
    try:
        with open(os.path.join(TARGET_DIR, ENCRYPTION_KEYS_FILE), 'w') as f:
            for filename, key in keys.items():
                f.write(f"{filename}:{key}\n")
    except Exception as e:
        print(f"Error writing encryption keys: {e}", file=sys.stderr)

    # Create restore instructions
    create_restore_instructions()

    # Perform periodic tasks
    perform_periodic_tasks()

    # Perform self-check after setup
    check_directory_integrity()

    # Register startup self-check (optional)
    if SELF_CHECK_TASK:
        register_startup_self_check()


if __name__ == '__main__':
    main()

