import os
import time
import json
import socket
import subprocess
from datetime import datetime
from http.client import HTTPConnection
from threading import Thread

TARGET_DIR = "./target"
LOG_FILE = os.path.join(TARGET_DIR, "time_sync.log")
REMOTE_SERVER = "time.server.example"
REMOTE_PORT = 80
SERVICE_NAME = "time_sync_service"

def ensure_directory_exists(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as e:
        log_error(f"Failed to create directory {path}: {e}")
        raise

def log_message(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"[{timestamp}] {message}"
    print(log_entry)
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as log_file:
            log_file.write(log_entry + "\n")
    except Exception as e:
        print(f"Failed to write to log file: {e}")

def log_error(error_message):
    log_message(f"ERROR: {error_message}")

def collect_system_time_and_timezone():
    try:
        system_time = datetime.now().isoformat()
        timezone = time.tzname[time.daylight]
        uptime = get_system_uptime()
        return {"system_time": system_time, "timezone": timezone, "uptime": uptime}
    except Exception as e:
        log_error(f"Failed to collect system time and timezone: {e}")
        return None

def get_system_uptime():
    try:
        if os.name == "posix":
            with open("/proc/uptime", "r") as f:
                uptime_seconds = float(f.readline().split()[0])
            return str(datetime.timedelta(seconds=int(uptime_seconds)))
        elif os.name == "nt":
            result = subprocess.run(["net", "stats", "srv"], capture_output=True, text=True)
            for line in result.stdout.splitlines():
                if "Statistics since" in line:
                    return line.split("since")[1].strip()
            return "Unknown uptime"
        else:
            return "Unsupported OS"
    except Exception as e:
        log_error(f"Failed to retrieve system uptime: {e}")
        return "Error retrieving uptime"

def send_data_to_remote_server(data):
    try:
        connection = HTTPConnection(REMOTE_SERVER, REMOTE_PORT, timeout=5)
        headers = {"Content-Type": "application/json"}
        connection.request("POST", "/sync", body=json.dumps(data), headers=headers)
        response = connection.getresponse()
        if response.status == 200:
            log_message("Successfully sent data to remote server.")
        else:
            log_error(f"Server returned HTTP status {response.status}.")
    except (socket.error, Exception) as e:
        log_error(f"Failed to send data to remote server: {e}")
    finally:
        try:
            connection.close()
        except Exception:
            pass

def time_sync_task():
    for _ in range(3):  # Perform the task 3 times
        data = collect_system_time_and_timezone()
        if data:
            log_message(f"Collected data: {data}")
            send_data_to_remote_server(data)
        time.sleep(5)

def register_service():
    try:
        service_file_path = os.path.expanduser(f"~/Library/LaunchAgents/{SERVICE_NAME}.plist") if os.name == "posix" else None
        if os.name == "posix" and service_file_path:
            service_definition = f"""
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>{SERVICE_NAME}</string>
