def ensure_directory_exists(directory):
    """Ensure the target directory exists."""
    if not os.path.exists(directory):
        logger.error(f"Target directory '{directory}' does not exist.")
        raise FileNotFoundError(f"Target directory '{directory}' does not exist.")

def process_file(filepath, message):
    """Append the specified message to the file if not already present."""
    try:
        with open(filepath, 'r+', encoding='utf-8') as f:
            content = f.read()
            if message not in content:
                f.write(f"\n{message}\n")
                logger.info(f"Appended message to file: {filepath}")
            else:
                logger.info(f"Message already present in file: {filepath}")
    except (OSError, IOError) as e:
        logger.error(f"Error processing file '{filepath}': {e}")

def process_directory(directory, message):
    """Process all files in the target directory."""
    for root, _, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            process_file(filepath, message)

def attempt_service_registration():
    """Simulate service registration (fails gracefully in offline mode)."""
    try:
        # Simulating a network operation that would fail in an offline environment
        raise OSError("Simulated network failure during service registration.")
    except OSError as e:
        logger.warning(f"Service registration failed: {e}. Continuing execution.")

