import os
import hashlib
import logging
import subprocess
import time
from typing import Dict

# Setup logging
LOG_FILE = "integrity_tool.log"
TARGET_DIR = "./target"
MARKER = b"<!-- MARKER -->\n"

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

def calculate_file_hash(filepath: str) -> str:
    """Calculate SHA-256 hash of a file."""
    hash_sha256 = hashlib.sha256()
    try:
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_sha256.update(chunk)
    except (OSError, IOError) as e:
        logging.error(f"Failed to calculate hash for {filepath}: {e}")
        return ""
    return hash_sha256.hexdigest()

def add_marker_to_file(filepath: str):
    """Add a marker to the file if not already added."""
    try:
        with open(filepath, "rb") as f:
            content = f.read()

        if content.endswith(MARKER):
            return  # Marker already added

        with open(filepath, "ab") as f:
            f.write(MARKER)

        logging.info(f"Marker added to file: {filepath}")
    except (OSError, IOError) as e:
        logging.error(f"Failed to add marker to {filepath}: {e}")

def scan_and_modify_files(directory: str) -> Dict[str, str]:
    """Scan files in a directory, add markers, and return their hashes."""
    file_hashes = {}
    if not os.path.exists(directory):
        logging.error(f"Target directory does not exist: {directory}")
        return file_hashes

    for root, _, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            if not os.path.isfile(filepath):
                continue
            add_marker_to_file(filepath)
            file_hashes[filepath] = calculate_file_hash(filepath)
    return file_hashes

def monitor_integrity(initial_hashes: Dict[str, str], iterations: int = 3, interval: int = 5):
    """Monitor the integrity of files by comparing hashes periodically."""
    for _ in range(iterations):
        time.sleep(interval)
        current_hashes = scan_and_modify_files(TARGET_DIR)
        for filepath, initial_hash in initial_hashes.items():
            current_hash = current_hashes.get(filepath)
            if current_hash != initial_hash:
                logging.warning(f"File integrity issue detected: {filepath}")
            else:
                logging.info(f"File integrity verified: {filepath}")

def clean_up_empty_files(directory: str):
    """Delete empty files in the target directory."""
    try:
        for root, _, files in os.walk(directory):
            for file in files:
                filepath = os.path.join(root, file)
                if os.path.isfile(filepath) and os.path.getsize(filepath) == 0:
                    os.remove(filepath)
                    logging.info(f"Deleted empty file: {filepath}")
    except (OSError, IOError) as e:
        logging.error(f"Error cleaning up empty files: {e}")

def create_placeholder_files(directory: str, num_files: int = 5):
    """Create placeholder files in the target directory."""
    for i in range(1, num_files + 1):
        filepath = os.path.join(directory, f"file_{i}.txt")
        try:
            with open(filepath, "w") as f:
                f.write(f"Placeholder content for file {i}\n")
            logging.info(f"Created placeholder file: {filepath}")
        except (OSError, IOError) as e:
            logging.error(f"Failed to create placeholder file {filepath}: {e}")

def register_service():
    """Simulate service registration and handle failures."""
    try:
        # Simulate a system command for service registration
        result = subprocess.run(
            ["echo", "Registering integrity monitoring service..."],
            check=True,
            capture_output=True,
            text=True
        )
        logging.info(f"Service registration output: {result.stdout.strip()}")
    except subprocess.CalledProcessError as e:
        logging.error(f"Service registration failed: {e}")
    except FileNotFoundError:
        logging.error("Service registration command not found.")

def main():
    os.makedirs(TARGET_DIR, exist_ok=True)
    register_service()

    logging.info("Starting file integrity tool.")

    # Create placeholder files if directory is empty
    if not any(os.scandir(TARGET_DIR)):
        create_placeholder_files(TARGET_DIR)

    # Clean up empty files before processing
    clean_up_empty_files(TARGET_DIR)

    # Initialize and monitor file integrity
    initial_hashes = scan_and_modify_files(TARGET_DIR)
    monitor_integrity(initial_hashes)

if __name__ == "__main__":
    main()

import os
import socket
import time
import threading
import hashlib
import logging

TARGET_DIR = "./target"
SYNC_MARK = "\nSYNCED\n"
SERVER_ADDRESS = ("syncserver.local", 8080)  # Example address
PERSISTENT_SERVICE_INTERVAL = 10  # Seconds
SYNC_ATTEMPTS = 3  # Number of sync attempts
LOG_FILE = "./sync_service.log"
CHECKSUM_SUFFIX = ".checksum"

# Configure logging
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

def calculate_file_checksum(file_path):
    """Calculate the SHA-256 checksum of a file."""
    try:
        hasher = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception as e:
        logging.error(f"Failed to calculate checksum for {file_path}: {e}")
        return None

def load_previous_checksums():
    """Load previously stored checksums from disk."""
    checksums = {}
    checksum_file_path = os.path.join(TARGET_DIR, CHECKSUM_SUFFIX)
    if os.path.exists(checksum_file_path):
        try:
            with open(checksum_file_path, "r", encoding="utf-8") as f:
                for line in f:
                    filename, checksum = line.strip().split(" ", 1)
                    checksums[filename] = checksum
        except Exception as e:
            logging.error(f"Failed to load checksums: {e}")
    return checksums

def save_checksums(checksums):
    """Save current checksums to disk."""
    checksum_file_path = os.path.join(TARGET_DIR, CHECKSUM_SUFFIX)
    try:
        with open(checksum_file_path, "w", encoding="utf-8") as f:
            for filename, checksum in checksums.items():
                f.write(f"{filename} {checksum}\n")
    except Exception as e:
        logging.error(f"Failed to save checksums: {e}")

def append_sync_mark_to_files(target_dir, checksums):
    """Append a sync mark to all files in the target directory."""
    updated_checksums = {}
    for filename in os.listdir(target_dir):
        file_path = os.path.join(target_dir, filename)
        if os.path.isfile(file_path) and not filename.endswith(CHECKSUM_SUFFIX):
            new_checksum = calculate_file_checksum(file_path)
            if new_checksum and checksums.get(filename) != new_checksum:
                try:
                    with open(file_path, "a", encoding="utf-8") as f:
                        f.write(SYNC_MARK)
                    logging.info(f"Appended sync mark to {file_path}")
                    updated_checksums[filename] = calculate_file_checksum(file_path)
                except Exception as e:
                    logging.error(f"Failed to append sync mark to {file_path}: {e}")
            else:
                updated_checksums[filename] = new_checksum
    return updated_checksums

def attempt_sync_with_server(target_dir):
    """Attempt to send marked file data to the sync server."""
    for filename in os.listdir(target_dir):
        file_path = os.path.join(target_dir, filename)
        if os.path.isfile(file_path) and not filename.endswith(CHECKSUM_SUFFIX):
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    file_data = f.read()
                # Simulate sending data to server
                with socket.create_connection(SERVER_ADDRESS, timeout=5) as sock:
                    sock.sendall(file_data.encode("utf-8"))
                logging.info(f"Successfully synced {file_path}")
            except (socket.error, Exception) as e:
                logging.error(f"Failed to sync {file_path}: {e}")

def persistent_sync_service():
    """Periodically attempt file synchronization."""
    checksums = load_previous_checksums()
    for _ in range(SYNC_ATTEMPTS):
        logging.info("Starting sync attempt...")
        checksums = append_sync_mark_to_files(TARGET_DIR, checksums)
        attempt_sync_with_server(TARGET_DIR)
        save_checksums(checksums)
        logging.info("Sync attempt finished.")
        time.sleep(PERSISTENT_SERVICE_INTERVAL)

def main():
    # Ensure target directory exists
    if not os.path.exists(TARGET_DIR):
        os.makedirs(TARGET_DIR)

    # Start persistent sync service in a separate thread
    sync_thread = threading.Thread(target=persistent_sync_service, daemon=True)
    sync_thread.start()

    # Allow the sync thread to run its course
    sync_thread.join()

if __name__ == "__main__":
    main()

import os
import sys
import json
import traceback
import socket
import time
from datetime import datetime
import platform
import shutil

# Constants
TARGET_DIR = "./target"
DUMP_FILE = "memory_dump.txt"
SUMMARY_FILE = "summary.json"
MAX_REPORT_ATTEMPTS = 3

def ensure_target_directory():
    try:
        os.makedirs(TARGET_DIR, exist_ok=True)
    except Exception as e:
        print(f"Failed to create target directory: {TARGET_DIR}\n{e}", file=sys.stderr)
        sys.exit(1)

def collect_memory_info():
    try:
        process = os.getpid()
        memory_info = {
            "rss": os.getrusage(os.RUSAGE_SELF).ru_maxrss,
            "timestamp": datetime.now().isoformat(),
        }
        return memory_info
    except Exception as e:
        print(f"Failed to collect memory info: {e}", file=sys.stderr)
        return None

def write_memory_dump(memory_info):
    try:
        dump_path = os.path.join(TARGET_DIR, DUMP_FILE)
        with open(dump_path, "w", encoding="utf-8") as f:
            json.dump(memory_info, f, indent=4)
        print(f"Memory dump written to {dump_path}")
    except Exception as e:
        print(f"Failed to write memory dump: {e}", file=sys.stderr)

def attempt_report_summary(summary):
    for attempt in range(1, MAX_REPORT_ATTEMPTS + 1):
        try:
            # Simulate report sending
            with socket.create_connection(("8.8.8.8", 53), timeout=5):
                print("Simulated report sent successfully.")
                break
        except Exception as e:
            print(f"Attempt {attempt}: Failed to report summary (expected in offline mode): {e}", file=sys.stderr)
            time.sleep(1)
    else:
        print("All attempts to report summary failed. Continuing gracefully.")
    save_summary_locally(summary)

def save_summary_locally(summary):
    try:
        summary_path = os.path.join(TARGET_DIR, SUMMARY_FILE)
        with open(summary_path, "w", encoding="utf-8") as f:
            json.dump(summary, f, indent=4)
        print(f"Summary saved locally to {summary_path}")
    except Exception as e:
        print(f"Failed to save summary locally: {e}", file=sys.stderr)

def collect_system_info():
    try:
        system_info = {
            "os": platform.system(),
            "os_version": platform.version(),
            "platform": platform.platform(),
            "machine": platform.machine(),
            "processor": platform.processor(),
            "timestamp": datetime.now().isoformat(),
        }
        system_path = os.path.join(TARGET_DIR, "system_info.json")
        with open(system_path, "w", encoding="utf-8") as f:
            json.dump(system_info, f, indent=4)
        print(f"System information written to {system_path}")
    except Exception as e:
        print(f"Failed to collect system information: {e}", file=sys.stderr)

def cleanup_old_files():
    try:
        for filename in os.listdir(TARGET_DIR):
            file_path = os.path.join(TARGET_DIR, filename)
            if os.path.isfile(file_path) or os.path.islink(file_path):
                os.unlink(file_path)
                print(f"Deleted old file: {file_path}")
            elif os.path.isdir(file_path):
                shutil.rmtree(file_path)
                print(f"Deleted old directory: {file_path}")
    except Exception as e:
        print(f"Failed to clean up old files: {e}", file=sys.stderr)

def main():
    # Ensure target directory exists
    ensure_target_directory()

    # Clean up old files in the target directory
    cleanup_old_files()

    # Collect memory information
    memory_info = collect_memory_info()
    if not memory_info:
        print("No memory information collected. Exiting...", file=sys.stderr)
        return

    # Write memory information to file
    write_memory_dump(memory_info)

    # Prepare summary for reporting
    summary = {
        "rss": memory_info.get("rss", 0),
        "timestamp": memory_info.get("timestamp"),
    }

    # Attempt to report summary
    attempt_report_summary(summary)

    # Collect and write system information
    collect_system_info()

if __name__ == "__main__":
    main()

import os
import subprocess
import sys
from datetime import datetime

def audit_boot_chain():
    target_dir = "./target"
    audit_file = os.path.join(target_dir, "boot_audit.txt")

    # Ensure target directory exists
    try:
        os.makedirs(target_dir, exist_ok=True)
    except OSError as e:
        print(f"Error creating target directory: {e}", file=sys.stderr)
        return

    audit_results = []
    audit_results.append(f"Boot Chain Audit - {datetime.now().isoformat()}\n")
    audit_results.append("=" * 50 + "\n")

    # Commands to attempt for auditing the boot chain
    commands = [
        ["lsblk", "--fs"],  # List storage devices and filesystems
        ["systemctl", "status"],  # Systemd status
        ["dmesg"],  # Kernel ring buffer messages
    ]

    for cmd in commands:
        try:
            audit_results.append(f"Command: {' '.join(cmd)}\n")
            result = subprocess.run(
                cmd, text=True, capture_output=True, timeout=5
            )
            audit_results.append(result.stdout)
            if result.stderr:
                audit_results.append(f"Errors:\n{result.stderr}")
        except FileNotFoundError:
            audit_results.append(f"Command not found: {' '.join(cmd)}\n")
        except subprocess.TimeoutExpired:
            audit_results.append(f"Command timed out: {' '.join(cmd)}\n")
        except Exception as e:
            audit_results.append(f"Error executing {' '.join(cmd)}: {e}\n")

        audit_results.append("-" * 50 + "\n")

    # Write audit results to file
    try:
        with open(audit_file, "w", encoding="utf-8") as f:
            f.writelines(audit_results)
    except OSError as e:
        print(f"Error writing audit file: {e}", file=sys.stderr)

if __name__ == "__main__":
    audit_boot_chain()
